source_context:
  1: ---
  2: - name: Print Bloom Configuration Values
  3:   hosts: localhost
  4:   gather_facts: no
  5: 
  6:   tasks:
  7:     - name: Print configuration header
  8:       debug:
  9:         msg: "=== Bloom Configuration Values ==="
 10: 
 11:     - name: Print Basic Configuration
 12:       debug:
 13:         msg: |
 14:           📋 Basic Configuration:
 15:             FIRST_NODE: {{ FIRST_NODE | default('NOT SET') }}
 16:             GPU_NODE: {{ GPU_NODE | default('NOT SET') }}
 17:             DOMAIN: {{ DOMAIN | default('NOT SET') }}
 18:             CLUSTER_SIZE: {{ CLUSTER_SIZE | default('NOT SET') }}
 19:             SERVER_IP: {{ SERVER_IP | default('NOT SET') }}
 20: 
 21:     - name: Print Cluster Size Optimizations
 22:       debug:
 23:         msg: |
 24:           📏 Cluster Size Impact ({{ CLUSTER_SIZE | default('NOT SET') }}):
 25:           {% if CLUSTER_SIZE == 'small' %}
 26:             🔧 Cilium Operator Replicas: 1 (HelmChartConfig at bootstrap)
 27:             💾 Storage Provisioner: local-path-provisioner (high-performance local storage)
 28:             🎯 Target Scale: Up to 3 nodes, development/testing workloads
 29:             📝 Resource Profile: Minimal overhead, reduced HA for cost efficiency
 30:             📊 Hubble Observability: Disabled (saves resources)
 31:           {% elif CLUSTER_SIZE == 'medium' %}
 32:             🔧 Cilium Operator Replicas: 1 (HelmChartConfig at bootstrap)
 33:             💾 Storage Provisioner: local-path-provisioner (high-performance local storage)
 34:             🎯 Target Scale: 1-3 nodes, development/testing workloads
 35:             📝 Resource Profile: Minimal overhead, reduced HA for cost efficiency
 36:             📊 Hubble Observability: Disabled (saves resources)
 37:           {% elif CLUSTER_SIZE == 'large' %}
 38:             🔧 Cilium Operator Replicas: 2 (RKE2 chart default)
 39:             💾 Storage Provisioner: Longhorn (distributed storage with replication)
 40:             🎯 Target Scale: 10+ nodes, enterprise workloads
 41:             📝 Resource Profile: High availability and performance
 42:             📊 Hubble Observability: Disabled (security and performance)
 43:           {% else %}
 44:             🔧 Cilium Operator Replicas: 2 (default; use small/medium for 1 at bootstrap)
 45:             💾 Storage Provisioner: Longhorn (default distributed storage)
 46:             📝 Note: Set CLUSTER_SIZE (small/medium/large) to optimize deployment
 47:           {% endif %}
 48: 
 49:     - name: Print Storage Configuration
 50:       debug:
 51:         msg: |
 52:           💾 Storage Configuration:
 53:             CLUSTER_DISKS: {{ CLUSTER_DISKS | default('NOT SET') }}
 54:             CLUSTER_PREMOUNTED_DISKS: {{ CLUSTER_PREMOUNTED_DISKS | default('NOT SET') }}
 55:             NO_DISKS_FOR_CLUSTER: {{ NO_DISKS_FOR_CLUSTER | default('NOT SET') }}
 56: 
 57:     - name: Print SSL/TLS Configuration
 58:       debug:
 59:         msg: |
 60:           🔒 SSL/TLS Configuration:
 61:             USE_CERT_MANAGER: {{ USE_CERT_MANAGER | default('NOT SET') }}
 62:             CERT_OPTION: {{ CERT_OPTION | default('NOT SET') }}
 63:             TLS_CERT: {{ TLS_CERT | default('NOT SET') }}
 64:             TLS_KEY: {{ TLS_KEY | default('NOT SET') }}
 65:             ADDITIONAL_TLS_SAN_URLS: {{ ADDITIONAL_TLS_SAN_URLS | default('NOT SET') }}
 66:             LETSENCRYPT_EMAIL: {{ LETSENCRYPT_EMAIL | default('NOT SET') }}
 67: 
 68:     - name: Print GPU Configuration
 69:       debug:
 70:         msg: |
 71:           🎮 GPU Configuration:
 72:             GPU_STACK_FAMILY: {{ gpu_stack_family_resolved | default(GPU_STACK_FAMILY) | default('instinct') }}
 73:             GPU_DRIVER_SKIP_INSTALL: {{ GPU_DRIVER_SKIP_INSTALL | default(false) }}
 74:             GPU_INSTALL_HOST_TOOLS: {{ GPU_INSTALL_HOST_TOOLS | default(true) }}
 75:             amdgpu driver package (no ROCm): {{ GPU_DRIVER_VERSION | default(gpu_driver_default_version) | default('NOT SET') }}.{{ GPU_DRIVER_BUILD | default(gpu_driver_default_build) | default('NOT SET') }}
 76:             GPU Operator: {{ gpu_operator_path | default('NOT SET') }}
 77:             GPU Operator config: {{ gpu_operator_config_path | default('NOT SET') }}
 78:             DeviceConfig ROCm driver: {{ gpu_deviceconfig_driver_version | default('NOT SET') }}
 79:           {% if gpu_stack_tech_preview | default(false) | bool %}
 80:             ⚠️  TECH PREVIEW: the {{ gpu_stack_family_resolved | default('radeon') }} Enterprise AI stack
 81:                 (GPU Operator) for this release is a tech preview, not production qualified.
 82:           {% endif %}
 83:             Driver policy synopsis:
 84:               Supported existing driver table:
 85:                 ROCm 7.0.2 -> driver 30.10.2 -> DKMS 6.14.14.30100200-2226257
 86:                 ROCm 7.1.1 -> driver 30.20.1 -> DKMS 6.16.6.30200100-2255209
 87:                 ROCm 7.2.3 -> driver 30.30.3 -> DKMS 6.16.13.30300300-2327507
 88:                 ROCm 7.2.4 -> driver 30.30.4 -> DKMS 6.16.13.30300400-2341068
 89:                 ROCm 7.13.0 -> driver 31.30.0 -> DKMS 6.19.4.31300000-2337710
 90:                 ROCm 7.14.0 -> driver 31.40.0 -> DKMS 6.19.14.31400000-2364437
 91:               - Any exact tuple above: retain and continue.
 92:               - Existing unrecognized amdgpu DKMS driver: halt with remediation instructions.
 93:               - Existing host ROCm without an identifiable supported DKMS driver:
 94:                 halt rather than replace its inbox/unknown driver.
 95:               - Fresh/inbox-only host: install 31.40.314000-1 -> driver 31.40.0
 96:                 -> DKMS 6.19.14; host ROCm is not installed or required.
 97:               - Missing amd-smi with host tools enabled: install the standalone
 98:                 package matching the effective driver, with minimal dependencies.
 99: 
100:     - name: Print RKE2 Configuration
101:       debug:
102:         msg: |
103:           ⚙️ RKE2 Configuration:
104:             RKE2_INSTALLATION_URL: {{ RKE2_INSTALLATION_URL | default('NOT SET') }}
105:             RKE2_VERSION: {{ RKE2_VERSION | default('NOT SET') }}
106: 
107:     - name: Print Advanced Configuration
108:       debug:
109:         msg: |
110:           🔧 Advanced Configuration:
111:             ENABLE_CLUSTERFORGE: {{ ENABLE_CLUSTERFORGE | default('NOT SET') }}
112:             CLUSTERFORGE_AIRGAP_ARCHIVE: {{ CLUSTERFORGE_AIRGAP_ARCHIVE | default('NOT SET') }}
113:             ENABLE_CLUSTERFORGE_OIDC: {{ ENABLE_CLUSTERFORGE_OIDC | default('NOT SET') }}
114:             OIDC_ISSUER_URL: {{ OIDC_ISSUER_URL | default('NOT SET') }}
115:             OIDC_CLIENT_ID: {{ OIDC_CLIENT_ID | default('NOT SET') }}
116:             OIDC_CLIENT_SECRET: {{ OIDC_CLIENT_SECRET | default('NOT SET') }}
117:             ADDITIONAL_OIDC_PROVIDERS: {{ ADDITIONAL_OIDC_PROVIDERS | default('NOT SET') }}
118: 
119:     - name: Print Command Line Options
120:       debug:
121:         msg: |
122:           💻 Command Line Options:
123:             USE_SUDO: {{ USE_SUDO | default('NOT SET') }}
124:             DEBUG_MODE: {{ DEBUG_MODE | default('NOT SET') }}
125:             SKIP_PREFLIGHT_CHECKS: {{ SKIP_PREFLIGHT_CHECKS | default('NOT SET') }}
126:             FORCE_REINSTALL: {{ FORCE_REINSTALL | default('NOT SET') }}
127: 
128:     - name: Print all variables (raw)
129:       debug:
130:         msg: "All ansible vars: {{ vars | dict2items | selectattr('key', 'match', '^[A-Z_]+$') | list }}"
131: 
132:     - name: Configuration check complete
133:       debug:
134:         msg: "=== Configuration Print Complete ==="
